const rooms=document.querySelector('#rooms'),nav=document.querySelector('#nav'),detail=document.querySelector('#detail');
function roomContent(a){
 let content=`<div class="room-head"><span class="room-label">${String(a.id).padStart(2,'0')} · ${a.name}</span><span class="room-code">${a.type}</span></div><span class="room-sub">${a.agents.length} AGENTS / ONLINE</span>`;
 if(a.groups){let gx=15,gy=60; a.groups.forEach((g,gi)=>{content+=`<div style="position:absolute;left:${gx+gi*220}px;top:48px;width:200px;border-top:1px solid ${a.color}55;padding-top:5px;font:7px DM Mono;color:${a.color}">${g[0]}</div>`;g.slice(1,10).forEach((n,i)=>{const x=gx+gi*220+(i%3)*62,y=gy+38+Math.floor(i/3)*70;content+=sprite(n,x,y,a.color,i)});});}
 else {a.agents.slice(0,10).forEach((n,i)=>{let cols=Math.max(2,Math.floor((a.w-25)/68));let x=18+(i%cols)*68,y=62+Math.floor(i/cols)*70;content+=sprite(n,x,y,a.color,i)});}
 return content;
}
function sprite(n,x,y,c,i){return `<div class="desk" style="left:${x-14}px;top:${y-13}px"></div><div class="agent ${i%3===0?'working':''}" style="left:${x}px;top:${y}px;--room-color:${c};--shirt:${['#496b77','#5a647d','#5c7359','#755c69'][i%4]}"><i class="head"></i><i class="body"></i><i class="legs"></i><span class="agent-name">${n}</span></div>`}
areas.forEach((a,i)=>{a.status=i===3?'alert':i===1||i===7?'thinking':'active';let el=document.createElement('article');el.className='room';el.dataset.id=a.id;el.dataset.status=a.status;el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label',`${a.name}: ${a.agents.length} agentes`);el.style.cssText=`left:${a.x}px;top:${a.y}px;width:${a.w}px;height:${a.h}px;--room-color:${a.color}`;el.innerHTML=roomContent(a);el.addEventListener('click',()=>selectArea(a));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectArea(a)}});rooms.append(el);let n=document.createElement('div');n.className='nav-item';n.style.setProperty('--room-color',a.color);n.innerHTML=`<span class="nav-num">${String(a.id).padStart(2,'0')}</span><span class="nav-name">${a.name}</span><span class="nav-count"><i class="status ${a.status}"></i>${a.agents.length}</span>`;n.onclick=()=>{focusRoom(a);selectArea(a);closeMenu()};nav.append(n)});
function selectArea(a){document.querySelectorAll('.room,.nav-item').forEach(e=>e.classList.remove('selected','active'));document.querySelector(`.room[data-id="${a.id}"]`).classList.add('selected');nav.children[a.id-1].classList.add('active');detail.style.setProperty('--accent',a.color);document.querySelector('#detailIndex').textContent=String(a.id).padStart(2,'0');document.querySelector('#detailType').textContent=a.type;document.querySelector('#detailType').style.color=a.color;document.querySelector('#detailName').textContent=a.name;document.querySelector('#detailDesc').textContent=a.desc;document.querySelector('#agentCount').textContent=String(a.agents.length).padStart(2,'0');document.querySelector('#signal').textContent=a.signal;document.querySelector('#agentList').innerHTML=a.agents.map(x=>`<div class="agent-chip" style="--accent:${a.color}">● ${x}</div>`).join('');detail.classList.add('open')}
document.querySelector('#close').onclick=()=>detail.classList.remove('open');
const sidebar=document.querySelector('#sidebar'),menu=document.querySelector('#menu'),scrim=document.querySelector('#scrim');
function closeMenu(){sidebar.classList.remove('open');scrim.classList.remove('open');menu.setAttribute('aria-expanded','false')}
menu.onclick=()=>{const open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);scrim.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open))};scrim.onclick=closeMenu;
let scale=.78,tx=25,ty=55,drag=false,sx=0,sy=0,stx=0,sty=0;const floor=document.querySelector('#floor'),vp=document.querySelector('#viewport');
function apply(){floor.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;document.querySelector('#zoomLabel').textContent=Math.round(scale*100)+'%'}
function setScale(v,cx=vp.clientWidth/2,cy=vp.clientHeight/2){let ns=Math.max(.42,Math.min(1.5,v));tx=cx-(cx-tx)*(ns/scale);ty=cy-(cy-ty)*(ns/scale);scale=ns;apply()}
vp.addEventListener('wheel',e=>{e.preventDefault();const r=vp.getBoundingClientRect();setScale(scale*(e.deltaY>0?.9:1.1),e.clientX-r.left,e.clientY-r.top)},{passive:false});vp.onpointerdown=e=>{if(e.target.closest('.room'))return;drag=true;sx=e.clientX;sy=e.clientY;stx=tx;sty=ty;vp.classList.add('dragging');vp.setPointerCapture(e.pointerId)};vp.onpointermove=e=>{if(drag){tx=stx+e.clientX-sx;ty=sty+e.clientY-sy;apply()}};vp.onpointerup=()=>{drag=false;vp.classList.remove('dragging')};
document.querySelector('#plus').onclick=()=>setScale(scale*1.15);document.querySelector('#minus').onclick=()=>setScale(scale*.85);document.querySelector('#reset').onclick=()=>{scale=.78;tx=25;ty=55;apply()};
document.querySelectorAll('.filter').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const f=btn.dataset.filter;document.querySelectorAll('.room').forEach(r=>r.classList.toggle('filtered',f!=='all'&&r.dataset.status!==f))});
function focusRoom(a){scale=Math.min(1.05,Math.max(.62,Math.min((vp.clientWidth-110)/a.w,(vp.clientHeight-140)/a.h)));tx=(vp.clientWidth-a.w*scale)/2-a.x*scale;ty=(vp.clientHeight-a.h*scale)/2-a.y*scale;apply()}
document.querySelector('#search').addEventListener('input',e=>{let q=e.target.value.toLowerCase().trim();document.querySelectorAll('.room').forEach((r,i)=>r.classList.toggle('highlight',q&&([areas[i].name,...areas[i].agents].join(' ').toLowerCase().includes(q))));});
function tick(){document.querySelector('#time').textContent=new Date().toISOString().slice(11,19)}setInterval(tick,1000);tick();apply();setTimeout(()=>selectArea(areas[0]),300);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){detail.classList.remove('open');closeMenu()}});
